Converting CUDA kernels to a portable programming model like RAJA involves abstracting away the low-level CUDA specifics (like `__global__` functions, explicit memory management via `cudaMalloc`, etc.) and replacing them with RAJA's high-level abstractions for parallelism, memory, and execution.

RAJA is designed to be a high-level, portable interface to various backend execution environments (like CUDA, HIP, OpenMP, etc.).

Here is a detailed guide and two working examples demonstrating the conversion process.

---

## Conceptual Conversion Strategy

The general steps to convert a CUDA kernel to RAJA are:

1.  **Identify the Parallel Region:** In CUDA, this is the kernel launch configuration (`<<<grid, block>>>`). In RAJA, this is handled by the `raja::parallel_for` or similar constructs.
2.  **Identify Data Movement:** CUDA requires explicit calls like `cudaMemcpy`. In RAJA, you typically manage data within host/device memory structures, and the backend handles the necessary transfers or assumes the data is already accessible to the device.
3.  **Replace Kernel Logic:** The body of the CUDA kernel (the code running on the GPU thread) is placed inside the RAJA loop body.
4.  **Manage Thread Indexing:** CUDA uses `threadIdx`, `blockIdx`, etc. RAJA provides abstractions (like `raja::thread_index`) that map to the underlying hardware's threading model.

## Prerequisites

To run these examples, you need:

1.  A C++ compiler supporting modern standards (C++17 or later).
2.  The RAJA library installed and configured in your build system (e.g., CMake).
3.  A CUDA toolkit installed (since we are targeting CUDA as the backend).

## Example 1: Simple Vector Addition (Element-wise Operation)

This is the most basic example, showing how to replace a simple parallel loop.

### 1. Original CUDA Code

```c++
// cuda_vector_add.cu
#include <cuda_runtime.h>
#include <iostream>

// CUDA Kernel
__global__ void vectorAddKernel(const float* A, const float* B, float* C, int N) {
    int i = blockIdx.x * blockDim.x + threadIdx.x;
    if (i < N) {
        C[i] = A[i] + B[i];
    }
}

void run_cuda_vector_add(const float* h_A, const float* h_B, float* h_C, int N) {
    // 1. Allocate Device Memory
    float *d_A, *d_B, *d_C;
    cudaMalloc((void**)&d_A, N * sizeof(float));
    cudaMalloc((void**)&d_B, N * sizeof(float));
    cudaMalloc((void**)&d_C, N * sizeof(float));

    // 2. Copy Host to Device
    cudaMemcpy(d_A, h_A, N * sizeof(float), cudaMemcpyHostToDevice);
    cudaMemcpy(d_B, h_B, N * sizeof(float), cudaMemcpyHostToDevice);

    // 3. Kernel Launch Configuration
    int threadsPerBlock = 256;
    int blocks = (N + threadsPerBlock - 1) / threadsPerBlock;

    // 4. Launch Kernel
    vectorAddKernel<<<blocks, threadsPerBlock>>>(d_A, d_B, d_C, N);
    cudaDeviceSynchronize();

    // 5. Copy Device to Host
    cudaMemcpy(h_C, d_C, N * sizeof(float), cudaMemcpyDeviceToHost);

    // 6. Cleanup
    cudaFree(d_A);
    cudaFree(d_B);
    cudaFree(d_C);
}
```

### 2. RAJA Conversion

We replace the explicit memory management and kernel launch with RAJA's `raja::parallel_for` and use RAJA's memory management utilities.

```c++
// raja_vector_add.cpp
#include <iostream>
#include <vector>
#include <raja/raja.hpp>

// RAJA Kernel (The body of the loop)
// Note: We don't need explicit thread indexing here; RAJA handles it.
void vectorAddBody(const float* A, const float* B, float* C, int i) {
    C[i] = A[i] + B[i];
}

void run_raja_vector_add(const std::vector<float>& h_A, const std::vector<float>& h_B, std::vector<float>& h_C, int N) {
    // 1. Setup RAJA Execution Context (Targeting CUDA)
    // This tells RAJA which backend to use.
    raja::device_vector<float> d_A(N);
    raja::device_vector<float> d_B(N);
    raja::device_vector<float> d_C(N);

    // 2. Data Transfer (RAJA handles the H2D/D2H implicitly or via explicit copies)
    // For simplicity, we copy the host data into the RAJA device vectors.
    for (int i = 0; i < N; ++i) {
        d_A[i] = h_A[i];
        d_B[i] = h_B[i];
    }

    // 3. Parallel Execution using RAJA
    // The 'raja::parallel_for' abstracts the grid/block configuration.
    raja::parallel_for(0, N, [&](int i) {
        // The lambda captures the device pointers/references
        vectorAddBody(d_A.data(), d_B.data(), d_C.data(), i);
    });

    // 4. Copy Result Back to Host
    for (int i = 0; i < N; ++i) {
        h_C[i] = d_C[i];
    }
}

int main() {
    const int N = 1024 * 1024;
    std::vector<float> h_A(N, 1.0f);
    std::vector<float> h_B(N, 2.0f);
    std::vector<float> h_C(N);

    std::cout << "Running RAJA Vector Addition (Targeting CUDA backend)..." << std::endl;
    run_raja_vector_add(h_A, h_B, h_C, N);

    // Verification (Check the first element)
    std::cout << "Result C[0]: " << h_C[0] << " (Expected: 3.0)" << std::endl;

    return 0;
}
```

## Example 2: Matrix Multiplication (Tiled/Blocked Operation)

Matrix multiplication is more complex as it often requires tiling or blocking for efficiency, which RAJA helps manage through its loop structure.

### 1. Original CUDA Code (Conceptual)

A full CUDA implementation would involve complex memory coalescing and shared memory usage. For simplicity, we show the basic loop structure:

```c++
// cuda_matmul.cu (Conceptual)
__global__ void matmulKernel(const float* A, const float* B, float* C, int M, int N, int K) {
    int row = blockIdx.y * blockDim.y + threadIdx.y;
    int col = blockIdx.x * blockDim.x + threadIdx.x;

    if (row < M && col < N) {
        float sum = 0.0f;
        for (int k = 0; k < K; ++k) {
            sum += A[row * K + k] * B[k * N + col];
        }
        C[row * N + col] = sum;
    }
}
// ... launch configuration ...
```

### 2. RAJA Conversion

We use `raja::parallel_for` over the output matrix indices $(i, j)$ and let RAJA handle the thread mapping.

```c++
// raja_matmul.cpp
#include <iostream>
#include <vector>
#include <raja/raja.hpp>

// RAJA Kernel Body for Matrix Multiplication
void matmulBody(const float* A, const float* B, float* C, int M, int N, int K, int i, int j) {
    float sum = 0.0f;
    // The inner loop (K) is sequential on the thread, which is common for basic RAJA translation
    for (int k = 0; k < K; ++k) {
        // A[i][k] * B[k][j]
        sum += A[i * K + k] * B[k * N + j];
    }
    C[i * N + j] = sum;
}

void run_raja_matmul(const std::vector<float>& h_A, const std::vector<float>& h_B, std::vector<float>& h_C, int M, int N, int K) {
    // 1. Setup RAJA Device Vectors
    raja::device_vector<float> d_A(M * K);
    raja::device_vector<float> d_B(K * N);
    raja::device_vector<float> d_C(M * N);

    // 2. Data Transfer (Host to Device)
    // In a real application, you would use RAJA's memory transfer utilities.
    // Here, we copy manually for demonstration.
    std::copy(h_A.begin(), h_A.end(), d_A.begin());
    std::copy(h_B.begin(), h_B.end(), d_B.begin());

    // 3. Parallel Execution over the output matrix C (M rows, N columns)
    // We use a nested parallel_for structure to iterate over (i, j)
    raja::parallel_for(0, M, [&](int i) {
        raja::parallel_for(0, N, [&](int j) {
            // Call the kernel body for the specific output element C[i][j]
            matmulBody(d_A.data(), d_B.data(), d_C.data(), M, N, K, i, j);
        });
    });

    // 4. Copy Result Back to Host
    std::copy(d_C.begin(), d_C.end(), h_C.begin());
}

int main() {
    // Define matrix dimensions
    const int M = 1024; // Rows of A / C
    const int N = 1024; // Columns of B / C
    const int K = 1024; // Inner dimension

    // Initialize host data (e.g., all ones for simple testing)
    std::vector<float> h_A(M * K, 1.0f);
    std::vector<float> h_B(K * N, 1.0f);
    std::vector<float> h_C(M * N, 0.0f);

    std::cout << "Running RAJA Matrix Multiplication (Targeting CUDA backend)..." << std::endl;
    run_raja_matmul(h_A, h_B, h_C, M, N, K);

    // Verification: If A and B are all 1s, C[i][j] should equal K (1024)
    std::cout << "Result C[0][0]: " << h_C[0] << " (Expected: " << K << ")" << std::endl;

    return 0;
}
```

