#include <vector>
#include <raja/raja.hpp>

// RAJA Kernel Body for Matrix Multiplication
void matmulBody(const float* A, const float* B, float* C, int M, int N, int K, int i, int j) {
    float sum = 0.0f;
    // The inner loop (K) is sequential on the thread, which is common for basic RAJA translation
    for (int k = 0; k < K; ++k) {
        // A[i][k] * B[k][j]
        sum += A[i * K + k] * B[k * N + j];
    }
    C[i * N + j] = sum;
}

void run_raja_matmul(const std::vector<float>& h_A, const std::vector<float>& h_B, std::vector<float>& h_C, int M, int N, int K) {
    // 1. Setup RAJA Device Vectors
    raja::device_vector<float> d_A(M * K);
    raja::device_vector<float> d_B(K * N);
    raja::device_vector<float> d_C(M * N);

    // 2. Data Transfer (Host to Device)
    // In a real application, you would use RAJA's memory transfer utilities.
    // Here, we copy manually for demonstration.
    std::copy(h_A.begin(), h_A.end(), d_A.begin());
    std::copy(h_B.begin(), h_B.end(), d_B.begin());

    // 3. Parallel Execution over the output matrix C (M rows, N columns)
    // We use a nested parallel_for structure to iterate over (i, j)
    raja::parallel_for(0, M, [&](int i) {
        raja::parallel_for(0, N, [&](int j) {
            // Call the kernel body for the specific output element C[i][j]
            matmulBody(d_A.data(), d_B.data(), d_C.data(), M, N, K, i, j);
        });
    });

    // 4. Copy Result Back to Host
    std::copy(d_C.begin(), d_C.end(), h_C.begin());
}

int main() {
    // Define matrix dimensions
    const int M = 1024; // Rows of A / C
    const int N = 1024; // Columns of B / C
    const int K = 1024; // Inner dimension

    // Initialize host data (e.g., all ones for simple testing)
