    RAJA::cuda_memcpy(d_A, h_A, sz, RAJA::cudaMemcpyHostToDevice);
    RAJA::cuda_memcpy(d_B, h_B, sz, RAJA::cudaMemcpyHostToDevice);

    // RAJA loop – 1‑D range
    RAJA::forall<RAJA::cuda_exec<256, RAJA::cuda_auto>>(
