## 1. Vector addition

### CUDA version

```cpp
// vector_add.cu
#include <cuda_runtime.h>
#include <cstdio>

__global__ void vecAdd(const float *A, const float *B, float *C, int N)
{
    int i = blockIdx.x * blockDim.x + threadIdx.x;
    if (i < N) C[i] = A[i] + B[i];
}

int main()
{
    const int N = 1<<20;          // 1M elements
    size_t sz = N*sizeof(float);

    float *h_A = (float*)malloc(sz);
    float *h_B = (float*)malloc(sz);
    float *h_C = (float*)malloc(sz);

    for (int i=0;i<N;i++) { h_A[i] = i; h_B[i] = 2*i; }

    float *d_A, *d_B, *d_C;
    cudaMalloc(&d_A, sz); cudaMalloc(&d_B, sz); cudaMalloc(&d_C, sz);
    cudaMemcpy(d_A, h_A, sz, cudaMemcpyHostToDevice);
    cudaMemcpy(d_B, h_B, sz, cudaMemcpyHostToDevice);

    int threads = 256;
    int blocks   = (N + threads - 1)/threads;
    vecAdd<<<blocks,threads>>>(d_A, d_B, d_C, N);
    cudaDeviceSynchronize();

    cudaMemcpy(h_C, d_C, sz, cudaMemcpyDeviceToHost);

    printf("C[0]=%f  C[5]=%f\n", h_C[0], h_C[5]);

    cudaFree(d_A); cudaFree(d_B); cudaFree(d_C);
    free(h_A); free(h_B); free(h_C);
}
```

