## 1. Vector addition

### CUDA version

```cpp
// vector_add.cu
#include <cuda_runtime.h>
#include <cstdio>

__global__ void vecAdd(const float *A, const float *B, float *C, int N)
{
    int i = blockIdx.x * blockDim.x + threadIdx.x;
    if (i < N) C[i] = A[i] + B[i];
}

int main()
{
    const int N = 1<<20;          // 1M elements
    size_t sz = N*sizeof(float);

    float *h_A = (float*)malloc(sz);
    float *h_B = (float*)malloc(sz);
    float *h_C = (float*)malloc(sz);

    for (int i=0;i<N;i++) { h_A[i] = i; h_B[i] = 2*i; }

    float *d_A, *d_B, *d_C;
    cudaMalloc(&d_A, sz); cudaMalloc(&d_B, sz); cudaMalloc(&d_C, sz);
    cudaMemcpy(d_A, h_A, sz, cudaMemcpyHostToDevice);
    cudaMemcpy(d_B, h_B, sz, cudaMemcpyHostToDevice);

    int threads = 256;
    int blocks   = (N + threads - 1)/threads;
    vecAdd<<<blocks,threads>>>(d_A, d_B, d_C, N);
    cudaDeviceSynchronize();

    cudaMemcpy(h_C, d_C, sz, cudaMemcpyDeviceToHost);

    printf("C[0]=%f  C[5]=%f\n", h_C[0], h_C[5]);

    cudaFree(d_A); cudaFree(d_B); cudaFree(d_C);
    free(h_A); free(h_B); free(h_C);
}
```

### RAJA version

```cpp
// vector_add_raja.cpp
#include <RAJA/RAJA.hpp>
#include <cstdio>
#include <cstdlib>

int main()
{
    constexpr int N = 1<<20;          // 1M elements
    size_t sz = N*sizeof(float);

    float *h_A = (float*)malloc(sz);
    float *h_B = (float*)malloc(sz);
    float *h_C = (float*)malloc(sz);

    for (int i=0;i<N;i++) { h_A[i] = i; h_B[i] = 2*i; }

    // Allocate device memory
    float *d_A, *d_B, *d_C;
    RAJA::cuda_malloc(&d_A, sz);
    RAJA::cuda_malloc(&d_B, sz);
    RAJA::cuda_malloc(&d_C, sz);

    // Copy to device
    RAJA::cuda_memcpy(d_A, h_A, sz, RAJA::cudaMemcpyHostToDevice);
    RAJA::cuda_memcpy(d_B, h_B, sz, RAJA::cudaMemcpyHostToDevice);

    // RAJA loop – 1‑D range
    RAJA::forall<RAJA::cuda_exec<256, RAJA::cuda_auto>>(
        RAJA::RangeSegment(0, N),
        [=] RAJA_DEVICE (int i) {
            d_C[i] = d_A[i] + d_B[i];
        });

    // Wait for kernel to finish
    RAJA::cuda_device_sync();

    // Copy back
    RAJA::cuda_memcpy(h_C, d_C, sz, RAJA::cudaMemcpyDeviceToHost);

    printf("C[0]=%f  C[5]=%f\n", h_C[0], h_C[5]);

    // Clean up
    RAJA::cuda_free(d_A); RAJA::cuda_free(d_B); RAJA::cuda_free(d_C);
    free(h_A); free(h_B); free(h_C);
}
```

**Build & run**

```bash
nvcc -std=c++17 vector_add_raja.cpp -lraja -lcudart -o vecadd_raja
./vecadd_raja
```

The RAJA code is *identical* in logic to the CUDA kernel, but the loop is expressed with `RAJA::forall` and a CUDA execution policy.  Switching to a different backend is as simple as changing the policy:

```cpp
RAJA::forall<RAJA::omp_parallel_for_exec>( ... );   // OpenMP
RAJA::forall<RAJA::serial_exec>( ... );             // Serial
```

