## 2. 2‑D 5‑point stencil (heat diffusion)

### CUDA version

```cpp
// stencil.cu
#include <cuda_runtime.h>
#include <cstdio>

__global__ void stencil(const float *in, float *out, int nx, int ny)
{
    int i = blockIdx.x * blockDim.x + threadIdx.x;   // column
    int j = blockIdx.y * blockDim.y + threadIdx.y;   // row

    if (i==0 || i==nx-1 || j==0 || j==ny-1) return; // boundary

    int idx = j*nx + i;
    out[idx] = 0.25f * ( in[idx-nx] + in[idx+nx] + in[idx-1] + in[idx+1] );
}

int main()
{
    const int nx = 512, ny = 512;
    size_t sz = nx*ny*sizeof(float);

    float *h_in  = (float*)malloc(sz);
    float *h_out = (float*)malloc(sz);
    for (int j=0;j<ny;j++)
        for (int i=0;i<nx;i++)
            h_in[j*nx+i] = (i+j)%5;   // arbitrary init

    float *d_in, *d_out;
    cudaMalloc(&d_in, sz); cudaMalloc(&d_out, sz);
    cudaMemcpy(d_in, h_in, sz, cudaMemcpyHostToDevice);

    dim3 threads(16,16);
    dim3 blocks((nx+threads.x-1)/threads.x, (ny+threads.y-1)/threads.y);
    stencil<<<blocks,threads>>>(d_in, d_out, nx, ny);
    cudaDeviceSynchronize();

    cudaMemcpy(h_out, d_out, sz, cudaMemcpyDeviceToHost);
    printf("out[256,256]=%f\n", h_out[256*nx+256]);

    cudaFree(d_in); cudaFree(d_out);
    free(h_in); free(h_out);
}
```

### RAJA version

```cpp
// stencil_raja.cpp
#include <RAJA/RAJA.hpp>
#include <cstdio>
#include <cstdlib>

int main()
{
    constexpr int nx = 512, ny = 512;
    size_t sz = nx*ny*sizeof(float);

    float *h_in  = (float*)malloc(sz);
    float *h_out = (float*)malloc(sz);
    for (int j=0;j<ny;j++)
        for (int i=0;i<nx;i++)
            h_in[j*nx+i] = (i+j)%5;

    // Device arrays
    float *d_in, *d_out;
    RAJA::cuda_malloc(&d_in, sz);
    RAJA::cuda_malloc(&d_out, sz);
    RAJA::cuda_memcpy(d_in, h_in, sz, RAJA::cudaMemcpyHostToDevice);

    // 2‑D layout for 1‑D indexing
    using Layout = RAJA::Layout<2>;
    Layout layout{nx, ny};

    // RAJA kernel – 2‑D loop
    RAJA::kernel<RAJA::cuda_exec<256, RAJA::cuda_auto>>(
        RAJA::make_tuple(RAJA::RangeSegment(0, nx),
                         RAJA::RangeSegment(0, ny)),
        [=] RAJA_DEVICE (int i, int j) {
            if (i==0 || i==nx-1 || j==0 || j==ny-1) return;
            int idx = j*nx + i;
            d_out[idx] = 0.25f * ( d_in[idx-nx] + d_in[idx+nx] +
                                   d_in[idx-1]  + d_in[idx+1] );
        });

    RAJA::cuda_device_sync();

    RAJA::cuda_memcpy(h_out, d_out, sz, RAJA::cudaMemcpyDeviceToHost);
    printf("out[256,256]=%f\n", h_out[256*nx+256]);

    RAJA::cuda_free(d_in); RAJA::cuda_free(d_out);
    free(h_in); free(h_out);
}
```

**Build & run**

```bash
nvcc -std=c++17 stencil_raja.cpp -lraja -lcudart -o stencil_raja
./stencil_raja
```

**Why this works**

* `RAJA::kernel` is a generic multi‑dimensional loop construct.  
* The policy `RAJA::cuda_exec<256, RAJA::cuda_auto>` tells RAJA to launch a CUDA kernel with 256 threads per block (the second template argument is the *block size*; the third is the *auto* block‑size selection).  
* The lambda is marked `RAJA_DEVICE` so it can be called from device code.  
* Boundary checks are done inside the kernel just like in the CUDA version.

---

## Quick “switch‑backend” cheat sheet

| Backend | Policy |
|---------|--------|
| CUDA (default) | `RAJA::cuda_exec<threads, RAJA::cuda_auto>` |
| CUDA async | `RAJA::cuda_async_exec<threads, RAJA::cuda_auto>` |
| OpenMP | `RAJA::omp_parallel_for_exec` |
| Serial | `RAJA::serial_exec` |
| TBB | `RAJA::tbb_for_exec` |
| HIP | `RAJA::hip_exec<threads, RAJA::hip_auto>` |

Just replace the policy in the `forall`/`kernel` call and re‑compile with the appropriate compiler (e.g., `hipcc` for HIP).

---

### Take‑away

* **RAJA** keeps the *algorithm* (the body of the loop) unchanged.  
* The *execution policy* is the only thing that changes when you target a new platform.  
* The same source file can be compiled for CPU, GPU, or any other supported backend with a single policy switch.  

