## Example 1: Simple Vector Addition (Element-wise Operation)

This is the most basic example, showing how to replace a simple parallel loop.

### 1. Original CUDA Code

```c++
// cuda_vector_add.cu
#include <cuda_runtime.h>
#include <iostream>

// CUDA Kernel
__global__ void vectorAddKernel(const float* A, const float* B, float* C, int N) {
    int i = blockIdx.x * blockDim.x + threadIdx.x;
    if (i < N) {
        C[i] = A[i] + B[i];
    }
}

void run_cuda_vector_add(const float* h_A, const float* h_B, float* h_C, int N) {
    // 1. Allocate Device Memory
    float *d_A, *d_B, *d_C;
    cudaMalloc((void**)&d_A, N * sizeof(float));
    cudaMalloc((void**)&d_B, N * sizeof(float));
    cudaMalloc((void**)&d_C, N * sizeof(float));

    // 2. Copy Host to Device
    cudaMemcpy(d_A, h_A, N * sizeof(float), cudaMemcpyHostToDevice);
    cudaMemcpy(d_B, h_B, N * sizeof(float), cudaMemcpyHostToDevice);

    // 3. Kernel Launch Configuration
    int threadsPerBlock = 256;
    int blocks = (N + threadsPerBlock - 1) / threadsPerBlock;

    // 4. Launch Kernel
    vectorAddKernel<<<blocks, threadsPerBlock>>>(d_A, d_B, d_C, N);
    cudaDeviceSynchronize();

    // 5. Copy Device to Host
    cudaMemcpy(h_C, d_C, N * sizeof(float), cudaMemcpyDeviceToHost);

    // 6. Cleanup
    cudaFree(d_A);
    cudaFree(d_B);
    cudaFree(d_C);
}
```

### 2. RAJA Conversion

We replace the explicit memory management and kernel launch with RAJA's `raja::parallel_for` and use RAJA's memory management utilities.

```c++
// raja_vector_add.cpp
#include <iostream>
#include <vector>
#include <raja/raja.hpp>

// RAJA Kernel (The body of the loop)
// Note: We don't need explicit thread indexing here; RAJA handles it.
void vectorAddBody(const float* A, const float* B, float* C, int i) {
    C[i] = A[i] + B[i];
}

void run_raja_vector_add(const std::vector<float>& h_A, const std::vector<float>& h_B, std::vector<float>& h_C, int N) {
    // 1. Setup RAJA Execution Context (Targeting CUDA)
    // This tells RAJA which backend to use.
    raja::device_vector<float> d_A(N);
    raja::device_vector<float> d_B(N);
    raja::device_vector<float> d_C(N);

    // 2. Data Transfer (RAJA handles the H2D/D2H implicitly or via explicit copies)
    // For simplicity, we copy the host data into the RAJA device vectors.
    for (int i = 0; i < N; ++i) {
        d_A[i] = h_A[i];
        d_B[i] = h_B[i];
    }

    // 3. Parallel Execution using RAJA
    // The 'raja::parallel_for' abstracts the grid/block configuration.
    raja::parallel_for(0, N, [&](int i) {
        // The lambda captures the device pointers/references
        vectorAddBody(d_A.data(), d_B.data(), d_C.data(), i);
    });

    // 4. Copy Result Back to Host
    for (int i = 0; i < N; ++i) {
        h_C[i] = d_C[i];
    }
}

int main() {
    const int N = 1024 * 1024;
    std::vector<float> h_A(N, 1.0f);
    std::vector<float> h_B(N, 2.0f);
    std::vector<float> h_C(N);

    std::cout << "Running RAJA Vector Addition (Targeting CUDA backend)..." << std::endl;
    run_raja_vector_add(h_A, h_B, h_C, N);

    // Verification (Check the first element)
    std::cout << "Result C[0]: " << h_C[0] << " (Expected: 3.0)" << std::endl;

    return 0;
}
```

